// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount, address targetAddr) public {
        amount = bound(amount, 0, 1 ether);

        Reverter reverter = new Reverter();

        vm.deal(address(c), 1 ether);

        address chosen = address(reverter);

        bool ok;
        try c.sendMoney(chosen, amount, "") {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 dcount = c.depositsCount();
        assertTrue(ok || dcount > 0);
    }
}

contract Reverter {
    fallback() external payable {
        revert("revert");
    }
    receive() external payable {
        revert("revert");
    }
}
